"""Readable offline layer inspector and report; no network/base64 or rig changes."""
from pathlib import Path
import json,html
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'review/male-hand-art-kit';data=json.loads((OUT/'hand-contract.json').read_text());cases=data['cases']
# Short labels remain legible inside tightly cropped authoring references.
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',13)
for c in cases:
    guide=Image.new('RGBA',(941,1672));d=ImageDraw.Draw(guide);d.line([tuple(v) for v in c['polygon']]+[tuple(c['polygon'][0])],fill='#45bfff',width=2)
    for key,color in [('wrist','#00ffb0'),('grip','#ffce55'),('elbow','#ff7777'),('shoulder','#ff7777')]:
        x,y=c['anchors_pose'][key];d.ellipse((x-4,y-4,x+4,y+4),fill=color);d.text((x+7,y+4),key[0].upper(),font=font,fill=color)
        if key in ['shoulder','elbow']:d.ellipse((x-12,y-12,x+12,y+12),outline=color,width=1)
    w=c['anchors_pose']['wrist'];g=c['anchors_pose']['grip'];axis=c['wrist_axis'];d.line([(w[0]-axis[0]*32,w[1]-axis[1]*32),(g[0]+axis[0]*35,g[1]+axis[1]*35)],fill='#00ffb0',width=2)
    guide.save(OUT/'Hands'/c['id']/'guides.png')
    shot=Image.open(OUT/'Gallery'/(c['pose']+'-full.png')).convert('RGBA');bb=c['preview_crop'];Image.alpha_composite(shot,guide).crop(bb).resize(((bb[2]-bb[0])*3,(bb[3]-bb[1])*3)).save(OUT/'Gallery'/(c['id']+'-registration.png'))
style='body{max-width:1200px;margin:auto;padding:18px;background:#182024;color:#eee4d3;font:17px/1.55 system-ui;overflow-wrap:anywhere}a{color:#9cd7ef}img,canvas{max-width:100%;height:auto}figure{margin:24px 0}table{border-collapse:collapse;display:block;overflow:auto}td,th{padding:10px;border:1px solid #596267;text-align:left}select{max-width:100%}button,select,label{font:inherit;min-height:44px}label{display:inline-flex;align-items:center;margin-right:16px}input{width:20px;height:20px;margin-right:8px}.notice{border:2px solid #dfaf62;padding:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}@media(max-width:650px){.grid{grid-template-columns:1fr}body{padding:10px}}pre{white-space:pre-wrap}'
head='<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Male Hand Art Kit · без нових кистей</title><style>'+style+'</style>'
intro='<h1>Комплект художника для3 кистей</h1><p class="notice"><strong>Нові кисті не намальовані й не інтегровані.</strong> Це запасний шлях за пунктом7 завдання: точні робочі маски, порожні шаблони, реальні референси та прив’язки. Поточні кулаки/хвати тут показані як проблемне джерело. Зображень «ПІСЛЯ» немає.</p><p><a href="Avatar-Lab.html">Чинний Avatar Lab</a> · <a href="Technical-report.html">Технічний звіт та інструкція художнику</a> · <a href="hand-contract.json">Повний машинний контракт</a></p>'
controls='<h2>Окремі шари чинної кисті та робочі маски</h2><p>Перемикачі змінюють лише цей огляд. Шаблони не підключаються в гру. Бірюзовий контур показує зовнішню робочу область; фактична маска виключає захищені ділянки плеча й ліктя. W — wrist, G — grip, S — shoulder, E — elbow. Червоні круги захищені. Координати в таблиці та anchors.json — точні.</p><select id="hand"></select><div><label><input id="arm" type="checkbox" checked>Чинна рука</label><label><input id="weapon" type="checkbox" checked>Окрема зброя</label><label><input id="front" type="checkbox" checked>Чинні передні пальці</label><label><input id="mask" type="checkbox">Робоча маска</label><label><input id="guides" type="checkbox" checked>Прив’язки</label><label><input id="blank" type="checkbox">Порожні нові шари</label></div><p id="info"></p><canvas id="layers"></canvas><p>Порожні candidate-back/front/thumb.png — завдання для художника,0 пікселів нового малюнка. Перед/зад нового великого пальця визначається художником за контактною поверхнею.</p>'
script='const cases='+json.dumps(cases,ensure_ascii=False)+';'+'''const $=id=>document.getElementById(id);const cache=new Map();let token=0;window.handKitReady=false;cases.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.title;$('hand').append(o)});const load=path=>{if(!cache.has(path))cache.set(path,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Missing '+path));im.src=path}));return cache.get(path)};async function draw(){const t=++token;window.handKitReady=false;const r=cases[+$('hand').value],base='Hands/'+r.id+'/';const names=[['arm','reference-arm-full.png'],['weapon','reference-weapon-full.png'],['front','reference-existing-front.png'],['mask','edit-overlay.png'],['guides','guides.png']];if($('blank').checked)for(const n of ['back','front','thumb'])names.push(['blank','candidate-'+n+'.png']);const loaded=await Promise.all(names.map(async([id,name])=>[id,await load(base+name)]));if(t!==token)return;const [x0,y0,x1,y1]=r.preview_crop,c=$('layers');c.width=(x1-x0)*3;c.height=(y1-y0)*3;const cx=c.getContext('2d');cx.fillStyle='#e8e1d5';cx.fillRect(0,0,c.width,c.height);for(const[id,im]of loaded)if($(id).checked)cx.drawImage(im,x0,y0,x1-x0,y1-y0,0,0,c.width,c.height);$('info').textContent=r.id+' · вихідне полотно941×1672 · crop ['+r.preview_crop.join(', ')+'] · огляд×3; реєстрація джерела не змінена';window.handKitReady=true}for(const id of ['hand','arm','weapon','front','mask','guides','blank'])$(id).onchange=draw;draw();'''
figs=[]
for c in cases:
 figs.append('<section><h2>'+html.escape(c['title'])+'</h2><p><strong>ДО / чинний стан; нової художньої версії ще немає.</strong></p><div class="grid"><figure><img src="Gallery/'+c['id']+'-before.png"><figcaption>Реальний поточний рендер×3</figcaption></figure><figure><img src="Gallery/'+c['id']+'-registration.png"><figcaption>Точки/робоча зона, не нова анатомія</figcaption></figure></div><p><a href="Hands/'+c['id']+'/anchors.json">Матриці й координати</a> · <a href="Hands/'+c['id']+'/edit-region.png">Робоча маска941×1672</a> · <a href="Hands/'+c['id']+'/wrist-blend-weight.png">Вага стику зап’ястя</a></p><figure><img src="Gallery/'+c['id']+'-breathing.webp"><figcaption>Чинний хват,4 секунди,32 реальні кадри. Нові кисті не тестувалися: їх немає.</figcaption></figure></section>')
for pose in ['pistol','rifle']:figs.append('<h2>'+pose+' · повноростовий рендер і чинне дихання</h2><div class="grid"><img src="Gallery/'+pose+'-full.png"><img src="Gallery/'+pose+'-breathing.webp"></div>')
rows=''.join('<tr><td>'+r['id']+'</td><td>'+', '.join(f'{v:.6f}' for v in r['anchors_pose']['wrist'])+'</td><td>'+', '.join(f'{v:.6f}' for v in r['anchors_pose']['grip'])+'</td><td>'+str(r['edit_bbox'])+'</td></tr>' for r in cases)
(OUT/'Report.html').write_text(head+intro+controls+'<h2>Параметри поз</h2><table><tr><th>Кисть</th><th>Зап’ястя X,Y</th><th>Хват X,Y</th><th>Робочий bbox [x0,y0,x1,y1),px</th></tr>'+rows+'</table>'+''.join(figs)+'<script>'+script+'</script></html>')
print('Offline report generated:3-case layer inspector; no after artwork claimed')
